 // official bank filters
 const refilterOfficial=()=>{const ex=$('#officialExam')?.value||'',yr=$('#officialYear')?.value.trim()||'';const filtered=state.officialQuestions.filter(q=>(!ex||(q.exam||q.sourceTitle)===ex)&&(!yr||String(q.year)===yr));const list=$('#officialList');if(list)list.innerHTML=officialListHtml(filtered)};$('#officialExam')?.addEventListener('change',refilterOfficial);$('#officialYear')?.addEventListener('input',refilterOfficial);
