 $('#createUser')?.addEventListener('click',createUser);$$('.blockUser').forEach(b=>b.onclick=()=>toggleBlock(b.dataset.id));$$('.editUser').forEach(b=>b.onclick=()=>editUser(b.dataset.id));$$('.unlockGrade').forEach(x=>x.onchange=()=>toggleArrayPermission(x.dataset.id,'unlockedGrades',Number(x.value),x.checked));$$('.unlockSubject').forEach(x=>x.onchange=()=>toggleArrayPermission(x.dataset.id,'unlockedSubjects',x.value,x.checked));$$('.unlockExam').forEach(x=>x.onchange=()=>{const u=state.users.find(y=>y.id===x.dataset.id),val=x.checked;(async()=>{try{if(CLOUD.enabled&&cloudSession){const saved=await cloudProfileUpdate(u.id,{exams_unlocked:val});u.examsUnlocked=saved.exams_unlocked!==false}else u.examsUnlocked=val;audit('provas',`${u.username}: ${val?'liberadas':'bloqueadas'}`)}catch(e){alert(e.message);render()}})()});$('#importQuestions')?.addEventListener('click',importQuestions);$('#runDuplicates')?.addEventListener('click',()=>{const r=duplicateReport();const el=$('#importStatus');el.textContent=`Duplicatas exatas: ${r.exact.length}. Quase duplicatas por normalização: ${r.near.length}.`;el.classList.remove('hidden')});$$('.gradeManual').forEach(b=>b.onclick=()=>gradeManual(b.dataset.id));$('#adminBackup')?.addEventListener('click',()=>download('estudaplus_admin_backup.json',JSON.stringify(state,null,2)));$('#clearDemo')?.addEventListener('click',()=>{if(confirm('Zerar progresso de todos os alunos?')){for(const u of state.users.filter(x=>x.role==='student'))state.stats[u.id]=blankStats();audit('progresso','todos os alunos zerados');render()}});
