// ---------- handlers ----------
function calcKey(k){const d=$('#calcDisplay');if(!d)return;if(k==='C'){d.value='';return}if(k==='='){if(!/^[0-9+\-*/().%\s]+$/.test(d.value))return d.value='erro';try{d.value=String(Function(`"use strict";return (${d.value})`)())}catch{d.value='erro'}return}d.value+=k}
function submitDiscursive(){const q=ui.question,ans=$('#discAnswer')?.value.trim();if(!ans)return alert('Escreva uma resposta.');const u=targetStudent(),id=`MAN-${Date.now()}`;const item={id,kind:'Questão discursiva',studentId:u.id,studentName:u.name,qid:q.id,prompt:q.prompt,answer:ans,status:'pending',createdAt:new Date().toISOString()};state.manualQueue.push(item);cloudSubmitManual(item);if(q.n!=null&&q.n>=0)answeredAdd(stats(u.id),q.n);else if(!stats(u.id).answeredCustom.includes(q.id))stats(u.id).answeredCustom.push(q.id);stats(u.id).questions++;recalc(stats(u.id));state.sessionDrafts[u.id]=null;localSave();alert('Resposta enviada para correção manual.');nextTrainingQuestion()}
function saveEssay(submit){const u=targetStudent(),text=$('#essayText')?.value||'';let d=state.essays[u.id].find(x=>x.status==='draft');if(!d){d={id:`RED-${Date.now()}`,prompt:ui.essayPrompt,text:'',status:'draft',startedAt:ui.essayStarted,updatedAt:new Date().toISOString()};state.essays[u.id].push(d)}d.text=text;d.prompt=ui.essayPrompt;d.updatedAt=new Date().toISOString();if(submit){d.status='pending';const item={id:`MAN-${Date.now()}`,kind:'Redação',studentId:u.id,studentName:u.name,essayId:d.id,prompt:d.prompt,answer:d.text,status:'pending',createdAt:new Date().toISOString()};state.manualQueue.push(item);cloudSubmitManual(item);ui.essayStarted=Date.now();alert('Redação enviada para correção.')}localSave();render()}
function startEssayTimer(){const el=$('#essayTimer');if(!el)return;const update=()=>{if(!document.body.contains(el))return;el.textContent=fmtTime(Date.now()-ui.essayStarted);setTimeout(update,1000)};update()}
function startExamTimer(){const el=$('#examTimer');if(!el)return;const update=()=>{if(!document.body.contains(el)||!ui.exam)return;const left=Math.max(0,ui.exam.limitMs-(Date.now()-ui.exam.startedAt));el.textContent=fmtTime(left);if(left<=0&&!ui.exam.finished){finishExam();return}setTimeout(update,1000)};update()}
function wireLoop(){let a=0,sum=0,step=0;$('#loopStep')?.addEventListener('click',()=>{if(sum<6){a++;sum+=a;step++}$('#loopState').textContent=`Etapa ${step} · a = ${a} · soma = ${sum}${sum<6?' · condição verdadeira':' · 6 < 6 é falso: terminou'}`});$('#loopReset')?.addEventListener('click',()=>{a=0;sum=0;step=0;$('#loopState').textContent='Etapa 0 · a = 0 · soma = 0'})}
async function createUser(){const name=$('#newName').value.trim(),username=$('#newUsername').value.trim().toLowerCase(),password=$('#newPassword').value,grade=Number($('#newGrade').value);if(!name||!username||!password)return alert('Preencha todos os campos.');if(state.users.some(u=>u.username.toLowerCase()===username))return alert('Usuário já existe.');try{let u;if(CLOUD.enabled&&cloudSession){alert('Por enquanto, crie a conta em Supabase → Authentication → Users → Add user. O perfil aparecerá automaticamente no Estuda+ depois.');return}else{const id=`u${Date.now()}`;u=defaultUser(id,name,username,password,'student',grade)}state.users.push(u);state.stats[u.id]=blankStats();normalize();audit('criar usuário',username);render()}catch(e){alert(e.message)}}
async function toggleBlock(id){const u=state.users.find(x=>x.id===id),next=!u.blocked;try{if(CLOUD.enabled&&cloudSession)await cloudProfileUpdate(id,{blocked:next});u.blocked=next;audit(u.blocked?'bloquear usuário':'desbloquear usuário',u.username);render()}catch(e){alert(e.message)}}
async function editUser(id){const u=state.users.find(x=>x.id===id),name=prompt('Nome',u.name),grade=prompt('Série (5 a 12)',u.grade),patch={};if(name)patch.name=name;if(grade&&Number(grade)>=5&&Number(grade)<=12){patch.grade=Number(grade);if(!u.unlockedGrades?.length)patch.unlocked_grades=[Number(grade)]}try{if(CLOUD.enabled&&cloudSession){const dbPatch={};if(patch.name)dbPatch.name=patch.name;if(patch.grade)dbPatch.grade=patch.grade;if(patch.unlocked_grades)dbPatch.unlocked_grades=patch.unlocked_grades;await cloudProfileUpdate(id,dbPatch)}Object.assign(u,patch);audit('editar usuário',u.username);render()}catch(e){alert(e.message)}}
async function toggleArrayPermission(id,field,value,checked){const u=state.users.find(x=>x.id===id);if(!u)return;const a=[...(u[field]||[])];if(checked&&!a.includes(value))a.push(value);const next=checked?a:a.filter(x=>x!==value);if(field==='unlockedGrades')next.sort((a,b)=>a-b);try{if(CLOUD.enabled&&cloudSession){const dbField=field==='unlockedGrades'?'unlocked_grades':'unlocked_subjects';const saved=await cloudProfileUpdate(id,{[dbField]:next});const fresh=cloudProfileFromRow(saved,u.email||'');u.unlockedGrades=fresh.unlockedGrades;u.unlockedSubjects=fresh.unlockedSubjects}else u[field]=next;audit('permissão',`${u.username}: ${field} ${checked?'liberou':'removeu'} ${value}`);render()}catch(e){alert(e.message);render()}}
async function importQuestions(){const file=$('#questionFile').files[0],status=$('#importStatus');if(!file)return alert('Escolha um arquivo.');try{const rows=await readQuestionFile(file),built=rows.map((r,i)=>importedQuestion(r,i,String(r.source_type||'').toLowerCase()==='official'));const before=duplicateReport(candidateBank().concat(built));let added=0;for(const q of built){if(!q.prompt)continue;if(q.questionType==='multiple_choice'&&q.options.length!==6)continue;const sem=`${q.subject}|${q.grade}|${q.area}|${normalizePrompt(q.prompt)}`;const exists=candidateBank().some(x=>`${x.subject}|${x.grade}|${x.area}|${normalizePrompt(x.prompt)}`===sem);if(exists)continue;if(q.origin.type==='official')state.officialQuestions.push(q);else state.customQuestions.push(q);added++}audit('importar questões',`${file.name}: ${added} adicionadas`);status.textContent=`Importadas: ${added}. Duplicatas/quase duplicatas rejeitadas: ${built.length-added}.`;status.classList.remove('hidden');localSave()}catch(e){status.textContent=e.message;status.classList.remove('hidden')}}
async function gradeManual(id){const item=state.manualQueue.find(x=>x.id===id),score=Number($(`.manualScore[data-id="${id}"]`).value),comment=$(`.manualComment[data-id="${id}"]`).value;item.status='graded';item.score=score;item.comment=comment;item.gradedAt=new Date().toISOString();const e=state.essays[item.studentId]?.find(x=>x.id===item.essayId);if(e){e.status='graded';e.score=score;e.comment=comment;e.updatedAt=new Date().toISOString()}await cloudGradeSubmission(item);audit('correção manual',`${item.studentName}: ${score}`);render()}

// ---------- keyboard ----------
document.addEventListener('keydown',e=>{if(!me()||ui.page!=='train'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(/^[1-6]$/.test(e.key)&&!ui.corrected)selectAnswer(Number(e.key)-1);else if(['c','d','f'].includes(e.key.toLowerCase())&&!ui.corrected)setCDF(e.key.toUpperCase());else if(e.key.toLowerCase()==='h')$('#hintBtn')?.click();else if(e.key.toLowerCase()==='n'&&ui.corrected)$('#nextQ')?.click();else if(e.key.toLowerCase()==='r')$('#scratch')?.focus()});

// ---------- startup ----------
if(location.protocol!=='file:'&&'serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{})}
decodeData().catch(e=>{APP.innerHTML=`<div class="login"><div class="card"><h2>O Estuda+ não conseguiu abrir.</h2><p>${esc(e.message)}</p><p>Mantenha <b>index.html</b>, a pasta <b>assets</b> e a pasta <b>data</b> juntas. Depois dê dois cliques em index.html.</p></div></div>`});
